/// Marks a chunk as dirty if it is currently loaded
public static void markChunkDirty(Level world, int chunkX, int chunkZ) {
    ChunkAccess chunk = world.getChunk(chunkX, chunkZ, ChunkStatus.FULL, false);
    if (chunk != null) {
        chunk.markUnsaved();
    }
}

